import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Одно и то же фото на телефоне может выглядеть идеально, а на сайте — полностью боком. Файл между двумя просмотрами никак не менялся, но изображение кажется повёрнутым.</p>\n<p>Причина — небольшой фрагмент метаданных под названием «ориентация EXIF». Это заметка внутри файла, которая записывает, как держали камеру, и читают её далеко не все программы.</p>\n<p>В этой статье объясняется, как работает ориентация EXIF, почему она ломается и как исправить фото навсегда, чтобы оно отображалось правильно в любом просмотрщике, форме и приложении.</p>\n<h2 id=\"what-is-exif-orientation\">Что такое ориентация EXIF?</h2>\n<p>EXIF — стандарт метаданных, который камеры и телефоны записывают в каждое фото. В нём фиксируются модель камеры, настройки экспозиции, дата и ориентация устройства.</p>\n<p>Поле ориентации — это одно число от 1 до 8. Каждое значение описывает сочетание поворота и отражения, например поворот на 90 градусов по часовой стрелке или отражение по горизонтали.</p>\n<p>Когда вы снимаете с телефоном, держа его боком, матрица фиксирует пиксели в одном неизменном направлении. Затем телефон записывает значение ориентации, которое говорит, как следует показывать снимок.</p>\n<p>Просмотрщики, которые понимают EXIF, поворачивают изображение на экране согласно этому значению. Те, что не понимают, показывают исходные пиксели, и поэтому фото выглядит боком.</p>\n<h2 id=\"the-eight-orientation-values\">Восемь значений ориентации — простыми словами</h2>\n<p>Значение 1 означает, что изображение уже стоит правильно и поворот не нужен. Большинство фото, снятых с телефоном в обычном положении, несут именно это значение.</p>\n<p>Значения 3, 6 и 8 описывают поворот. Значение 3 означает, что изображение перевёрнуто, значение 6 — что нужен поворот на 90 градусов по часовой стрелке, а значение 8 — на 90 градусов против часовой.</p>\n<p>Значения 2, 4, 5 и 7 добавляют отражение. Они появляются при съёмке на фронтальную камеру и при работе некоторых сканеров, где изображение одновременно отражается и поворачивается.</p>\n<p>Заучивать эти числа не нужно. Важно понять закономерность: фото, которое в одном просмотрщике выглядит неправильно, а в другом — правильно, почти всегда имеет значение ориентации, которое один просмотрщик игнорирует.</p>\n<p>На практике чаще всего встречаются три значения: 1, 6 и 8. Единица означает нормальную ориентацию, шестёрка — фото, снятое с телефоном, повёрнутым в одну сторону, а восьмёрка — в другую.</p>\n<p>Значения с отражением встречаются реже и почти всегда связаны с фронтальной камерой. Если селфи выглядит зеркально только в некоторых приложениях, причина почти наверняка в одном из значений 2, 4, 5 или 7.</p>\n<p>Проверить значение ориентации можно в свойствах файла или в просмотрщике метаданных. Там же обычно видны модель камеры, дата съёмки и другие поля EXIF.</p>\n<h2 id=\"why-phones-store-orientation-this-way\">Почему телефоны хранят ориентацию, а не поворачивают пиксели</h2>\n<p>Поворот самих пикселей требует времени и вычислительной мощности. Записать одно число в метаданные — мгновенно, поэтому телефоны идут быстрым путём и перекладывают работу на просмотрщики.</p>\n<p>Такой подход также сохраняет исходные данные матрицы нетронутыми. Файл остаётся ровно таким, каким его зафиксировала камера, а заметка об ориентации подсказывает каждой программе, как его показать.</p>\n<p>Для большинства пользователей это работает незаметно. Современные галереи, браузеры и соцсети читают значение ориентации, поэтому фото отображаются правильно, и никто об этом не задумывается.</p>\n<p>Проблема возникает на краях системы: старое ПО, формы загрузки, сервисы печати и простые просмотрщики, которые так и не научились читать эту заметку.</p>\n<h2 id=\"where-orientation-breaks\">Где ориентация ломается на практике</h2>\n<p>Формы загрузки — самое частое место поломки. Сайт вакансий или госуслуг может показать ваше фото боком, хотя в галерее оно выглядит нормально, потому что форма игнорирует EXIF.</p>\n<p>Почтовые клиенты — ещё один пример. Некоторые старые клиенты показывают вложенные фото в исходной ориентации, и получатель видит снимок боком, хотя отправителю он казался правильным.</p>\n<p>Сервисы печати тоже могут ломаться. Фото, напечатанное из файла, который полагается на заметку об ориентации, может выйти повёрнутым, если печатное ПО не читает метаданные.</p>\n<p>Даже некоторые соцсети исторически страдали от этой проблемы. Фото, загруженное с телефона, могло появиться в публикации повёрнутым, хотя в фотоплёнке тот же файл выглядел правильно.</p>\n<h2 id=\"detecting-an-orientation-problem\">Как понять, что проблема именно в ориентации</h2>\n<p>Фирменный симптом — непоследовательность. Если один и тот же файл в одном месте выглядит правильно, а в другом — неправильно, вероятная причина — метаданные ориентации, а не повреждённый файл.</p>\n<p>Откройте фото в двух разных программах. Если галерея телефона показывает его правильно, а просмотрщик на компьютере — боком, заметку EXIF читает одна программа и игнорирует другая.</p>\n<p>Ещё одна подсказка — направление ошибки. Проблемы ориентации всегда поворачивают на 90 или 180 градусов и никогда — на малый угол вроде трёх градусов, что указывало бы на наклонённую камеру.</p>\n<p>Если есть возможность, проверьте файл на втором устройстве. Фото, которое боком везде, включая вашу галерею, имеет по-настоящему повёрнутые пиксели и нуждается в обычном исправлении поворотом.</p>\n<h2 id=\"fixing-orientation-permanently\">Как исправить ориентацию навсегда</h2>\n<p>Постоянное исправление — повернуть сами пиксели и сбросить значение ориентации на 1. После этого файл отображается правильно в любом просмотрщике, читает он EXIF или нет.</p>\n<p><a href=\"/ru/povernut-otrazit-izobrazhenie/\">Инструмент поворота и отражения изображений</a> делает именно это. Когда вы поворачиваете изображение и скачиваете его, у экспортированного файла правильно ориентированные пиксели и чистая метка ориентации.</p>\n<p>Это лучше, чем полагаться на то, что просмотрщики истолкуют заметку. Исправленный файл работает в старом ПО, формах загрузки и сервисах печати, которые так и не научились читать EXIF.</p>\n<p>Сохраните исходный файл, прежде чем исправлять его, на случай, если когда-нибудь понадобится нетронутая версия. Исправленный файл — тот, которым стоит делиться, который стоит загружать и печатать.</p>\n<h2 id=\"orientation-vs-rotation\">Метаданные ориентации и настоящий поворот</h2>\n<p>Метаданные ориентации — это подсказка о том, как показывать изображение. Настоящий поворот меняет сами пиксели, поэтому подсказка больше не нужна.</p>\n<p>Представьте стикер на картине с надписью «эта сторона вверх». Просмотрщик, который читает стикер, вешает картину правильно, а тот, что игнорирует его, — боком.</p>\n<p>Поворот пикселей — как переписать картину правильно с самого начала. Стикер становится ненужным, и каждый просмотрщик показывает изображение верно.</p>\n<p>Поэтому правильное исправление поворотом постоянно. Оно убирает зависимость от того, согласны ли все программы по поводу одного поля метаданных.</p>\n<h2 id=\"selfies-and-mirroring\">Селфи, отражение и значения ориентации</h2>\n<p>Фронтальные камеры добавляют в историю ориентации свой поворот. Многие телефоны сохраняют зеркальное изображение и записывают отражение в значение ориентации, поэтому в галерее фото выглядит правильно.</p>\n<p>Когда просмотрщик игнорирует это значение, селфи выглядит зеркальным. Текст на футболке читается наоборот, а пробор оказывается не с той стороны головы.</p>\n<p>Исправление здесь — горизонтальное отражение, а не поворот. Отражение зеркалит пиксели обратно, и экспортированный файл больше не зависит от заметки об ориентации, чтобы выглядеть правильно.</p>\n<p>Если селфи нужны и отражение, и поворот, сначала сделайте отражение, а затем поворот. Проверяйте предпросмотр после каждого шага, чтобы видеть, что именно изменилось.</p>\n<h2 id=\"exif-and-privacy\">Ориентация EXIF и конфиденциальность</h2>\n<p>Поле ориентации — лишь одна часть метаданных EXIF. Тот же файл может нести GPS-координаты, модель камеры и дату съёмки.</p>\n<p>Эти дополнительные данные — вопрос конфиденциальности, когда вы делитесь фото публично. Опубликованный снимок может раскрыть место съёмки, даже если на самом изображении нет ничего узнаваемого.</p>\n<p>Поворот изображения в инструменте CompressMyPic удаляет данные GPS при экспорте. Ориентация исправляется, а запись о местоположении удаляется за тот же шаг.</p>\n<p>Если хотите проверить, что раскрывает фото перед публикацией, используйте <a href=\"/ru/prosmotr-metadannykh-izobrazheniya/\">инструмент просмотра метаданных изображения</a>, чтобы изучить поля EXIF. А чтобы удалить их полностью, используйте <a href=\"/ru/udalit-metadannye-izobrazheniya/\">инструмент удаления метаданных изображения</a>.</p>\n<h2 id=\"orientation-in-different-formats\">Ориентация в JPG, PNG и WebP</h2>\n<p>В JPG проблемы с ориентацией встречаются чаще всего, потому что почти каждый телефон сохраняет фото именно в JPG с полными данными EXIF. Поле ориентации записывается по умолчанию.</p>\n<p>Файлы PNG тоже могут нести данные EXIF, но многие инструменты для PNG удаляют их или вообще не записывают. У скриншота в PNG редко возникает проблема с ориентацией, ведь у снимка экрана нет направления камеры, которое нужно записывать.</p>\n<p>WebP тоже поддерживает ориентацию EXIF. Современные браузеры читают её правильно, но старые инструменты, которые конвертируют WebP в JPG, иногда теряют значение ориентации и выдают фото боком.</p>\n<p>HEIC, формат новых айфонов, также хранит ориентацию. Конвертация HEIC в JPG без учёта значения ориентации — частая причина перевёрнутых фото после конвертации.</p>\n<p>Скриншоты в PNG обычно не страдают от проблем с ориентацией, потому что у них нет данных с датчика камеры. Если скриншот всё же выглядит боком, причина почти всегда в самом приложении, а не в метаданных.</p>\n<p>Формат GIF ориентацию практически не использует: анимации хранят кадры как есть. Поэтому повёрнутый GIF нужно исправлять поворотом пикселей, а не надеяться на заметку в метаданных.</p>\n<p>При конвертации между форматами всегда проверяйте результат на другом устройстве. Ошибка ориентации после конвертации видна сразу, а исправляется за секунды поворотом уже сконвертированного файла.</p>\n<h2 id=\"orientation-after-conversion\">Проблемы с ориентацией после конвертации формата</h2>\n<p>Конвертация фото из одного формата в другой может сломать его ориентацию. Конвертер может скопировать пиксели, но потерять заметку EXIF, и останется фото боком без записи о том, как его следует показывать.</p>\n<p>Это часто случается при конвертации HEIC в JPG. Файл с айфона несёт значение ориентации, а конвертер, который его игнорирует, выдаёт JPG, который во всех просмотрщиках выглядит повёрнутым.</p>\n<p>Самый безопасный порядок — сначала исправить ориентацию, а потом конвертировать. Поверните изображение в <a href=\"/ru/povernut-otrazit-izobrazhenie/\">инструменте поворота и отражения</a>, скачайте исправленный файл и только затем конвертируйте его в другой формат.</p>\n<p>Если сконвертированный файл уже выглядит боком, поверните сам сконвертированный файл. Теперь важны пиксели, и обычное исправление поворотом их выправит.</p>\n<h2 id=\"orientation-and-social-media\">Ориентация в соцсетях и мессенджерах</h2>\n<p>Большинство крупных соцсетей сейчас правильно читают ориентацию EXIF. Фото, загруженное с телефона, обычно появляется в публикации, истории или аватаре правильно.</p>\n<p>Мессенджеры более разнородны. Одни читают значение ориентации, а другие показывают исходные пиксели, поэтому одно и то же фото в одном чате выглядит нормально, а в другом — боком.</p>\n<p>Аватары — особый случай. Многие платформы обрезают фото профиля в квадрат или круг, и боком исходное изображение даёт плохо кадрированную обрезку, даже когда ориентация читается правильно.</p>\n<p>Исправляйте ориентацию перед загрузкой в любое важное место. Исправленный файл убирает догадки и выглядит одинаково на всех платформах.</p>\n<h2 id=\"common-myths\">Частые мифы об ориентации изображений</h2>\n<p>Один миф гласит, что фото боком повреждено. Это не так. Пиксели целы, файл исправен, просто одна программа читает инструкцию по отображению, а другая — нет.</p>\n<p>Другой миф — что повторное сохранение файла в редакторе всегда это исправляет. Некоторые редакторы сохраняют значение ориентации нетронутым, и файл выходит ровно таким же боком, каким вошёл.</p>\n<p>Третий миф — что всё современное ПО читает EXIF. Большинство — да, но формы загрузки, печатные киоски и встроенные системы часто отстают на годы, и именно там ориентация ломается заметнее всего.</p>\n<p>Надёжное правило простое: если фото важно, исправьте пиксели. Файл с правильными пикселями и чистой меткой ориентации работает везде, без всяких мифов.</p>\n<h2 id=\"orientation-in-print-services\">Ориентация в сервисах печати и киосках</h2>\n<p>Печатные киоски — одни из худших нарушителей, игнорирующих ориентацию EXIF. Фото, которое на телефоне выглядит идеально, может напечататься боком из киоска, который читает только исходные пиксели.</p>\n<p>Исправление — привести файл в порядок до похода к киоску. Поверните пиксели в инструменте, скачайте исправленный файл и печатайте с этой версии, а не с оригинала.</p>\n<p>Онлайн-сервисы печати лучше, но не идеальны. Одни правильно читают заметку об ориентации, а другие полагаются на размеры файла, поэтому исправленный файл полностью убирает догадки.</p>\n<p>Для всего, за печать чего вы платите, всегда сначала проверяйте пробный отпечаток. Одна пробная копия стоит немного, а целый заказ перевёрнутых отпечатков — гораздо дороже.</p>\n<h2 id=\"orientation-and-backup-services\">Ориентация и облачные резервные копии</h2>\n<p>Облачные сервисы резервного копирования обычно сохраняют данные EXIF, поэтому фото после восстановления сохраняет заметку об ориентации. Проблема не в копии, а в программах, которые открывают восстановленный файл.</p>\n<p>Перенос фото между сервисами может лишить их метаданных. Файл, скачанный из одного облачного сервиса и загруженный в другой, может по пути потерять значение ориентации.</p>\n<p>Исправляйте ориентацию, прежде чем архивировать важные фото. Файл с правильными пикселями и чистой меткой ориентации переживёт любое количество переносов, не меняя того, как он выглядит.</p>\n<p>Для семейных фото и отсканированных воспоминаний этот шаг важнее всего. Фото, заархивированное боком, может оставаться боком годами, пока кто-нибудь не заметит это и не исправит.</p>\n<h2 id=\"orientation-in-old-software\">Ориентация в старом ПО и встроенных системах</h2>\n<p>Старые просмотрщики фото, дисплеи автомобилей и цифровые фоторамки часто полностью игнорируют EXIF. Они были созданы до того, как метаданные ориентации стали стандартом, и показывают исходные пиксели.</p>\n<p>Цифровая фоторамка, которая показывает ваши отпускные фото боком, не сломана. Она просто отображает пиксели так, как их зафиксировала камера, не читая заметку об ориентации.</p>\n<p>То же касается некоторых медицинских и промышленных систем обработки изображений, которые показывают файлы ровно так, как они хранятся. Исправленный файл работает в этих системах, а файл, зависящий от метаданных, — нет.</p>\n<p>Когда фото должно отображаться на технике, которую вы не контролируете, исправляйте пиксели. Это единственный подход, который работает на любом устройстве, старом или новом.</p>\n<p>Особенно это касается фото для документов и официальных порталов. Системы проверки часто работают на старом ПО, которое игнорирует EXIF, и фото боком отклоняется автоматически.</p>\n<p>То же правило действует для фоторамок и экранов в общественных местах. Файл с правильными пикселями покажется верно на любом экране, а файл с заметкой — только там, где заметку читают.</p>\n<p>Перед важной печатью или отправкой документов всегда открывайте исправленный файл в простом просмотрщике. Если он выглядит правильно там, он будет выглядеть правильно везде.</p>\n<h2 id=\"orientation-testing-checklist\">Быстрый чек-лист перед публикацией фото</h2>\n<p>Откройте фото в двух разных программах, прежде чем делиться им. Если в обеих оно выглядит правильно, ориентация, скорее всего, в порядке, и файл можно безопасно отправлять.</p>\n<p>Если есть возможность, проверьте фото на втором устройстве. Телефон и компьютер читают ориентацию по-разному, поэтому файл, который правильно выглядит на обоих, по-настоящему исправен.</p>\n<p>Если сомневаетесь, исправьте пиксели. Поворот в <a href=\"/ru/povernut-otrazit-izobrazhenie/\">инструменте поворота и отражения</a> занимает секунды, а исправленный файл убирает всю неопределённость в том, как он отобразится.</p>\n<p>Храните исходный файл в папке архива. Исправленная версия — та, которой стоит делиться, а оригинал сохраняет нетронутые данные матрицы на случай, если они когда-нибудь понадобятся.</p>\n<p>Практические шаги смотрите в статье <a href=\"/ru/blog/kak-povernut-ili-otrazit-izobrazhenie/\">Как повернуть или отразить изображение</a> и в полном обзоре <a href=\"/ru/blog/povorot-i-otrazhenie-izobrazheniy-polnoe-rukovodstvo/\">Поворот и отражение изображений: полное руководство</a>. Если на фото есть данные о местоположении, которые лучше удалить, прочитайте статью <a href=\"/ru/blog/riski-privatnosti-foto-gps-exif/\">Конфиденциальность фото: GPS, EXIF и риски метаданных</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Что такое ориентация EXIF простыми словами?","answer":"Это число, сохранённое внутри фото, которое записывает, как держали камеру. Просмотрщики, которые читают это число, показывают фото правильно, а те, что игнорируют его, показывают исходные пиксели, которые могут выглядеть боком или перевёрнутыми."},{"question":"Почему фото на телефоне выглядит нормально, а на сайте — боком?","answer":"Галерея телефона читает заметку об ориентации EXIF, а сайт — нет. Пиксели никогда не поворачивались, поэтому сайт показывает их в исходном направлении. Поворот изображения в редакторе переписывает пиксели и навсегда исправляет проблему."},{"question":"Фото боком — это повреждение или файл испорчен?","answer":"Нет. Пиксели целы, а файл исправен. Проблема лишь в том, что одна программа читает заметку об ориентации, а другая — нет. Правильное исправление поворотом заставляет файл отображаться корректно везде."},{"question":"Как навсегда исправить фото с неверной ориентацией?","answer":"Поверните сами пиксели в редакторе и экспортируйте результат — это сбрасывает значение ориентации к нормальному. Инструмент поворота и отражения делает именно это: у скачанного файла правильно ориентированные пиксели, и он больше не зависит от того, читают ли просмотрщики метаданные."},{"question":"Вызывает ли конвертация HEIC в JPG проблемы с ориентацией?","answer":"Может, если конвертер копирует пиксели, но теряет заметку об ориентации EXIF. Самый безопасный порядок — сначала исправить ориентацию, а потом конвертировать исправленный файл. Если сконвертированный файл уже выглядит боком, поверните сам сконвертированный файл."},{"question":"Могут ли данные EXIF раскрыть место съёмки фото?","answer":"Да. Те же метаданные, которые хранят ориентацию, могут хранить GPS-координаты, модель камеры и дату. Поворот изображения в инструменте CompressMyPic удаляет GPS-теги при экспорте, а инструменты просмотра и удаления метаданных позволяют изучить и удалить остальное."}];
